import type { IInputProps } from '@univerjs/design';
import type { LocaleKey } from '../../locale/types';
import type { IFindReplaceService } from '../../services/find-replace.service';
import { LocaleService } from '@univerjs/core';
import { Input, Pager } from '@univerjs/design';
import { useDependency } from '@univerjs/ui';
import { useState } from 'react';

export interface ISearchInputProps extends Pick<IInputProps, 'onFocus' | 'onBlur' | 'className' | 'onChange'> {
    findCompleted: boolean;
    findReplaceService: IFindReplaceService;
    matchesPosition: number;
    matchesCount: number;
    initialFindString: string;
}

export function SearchInput(props: ISearchInputProps) {
    const {
        findCompleted: findComplete,
        matchesCount,
        matchesPosition,
        initialFindString,
        findReplaceService,
        onChange,
        ...rest
    } = props;

    const localeService = useDependency(LocaleService);

    const [value, setValue] = useState(initialFindString);
    const noResult = findComplete && matchesCount === 0;
    const text = noResult
        ? localeService.t<LocaleKey>('find-replace.dialog.no-result')
        : matchesCount === 0
            ? ' '
            : undefined;

    function handleChangePosition(newIndex: number) {
        if (matchesPosition === matchesCount && newIndex === 1) {
            findReplaceService.moveToNextMatch();
        } else if (matchesPosition === 1 && newIndex === matchesCount) {
            findReplaceService.moveToPreviousMatch();
        } else if (newIndex < matchesPosition) {
            findReplaceService.moveToPreviousMatch();
        } else {
            findReplaceService.moveToNextMatch();
        }
    }

    return (
        <div className="univer-relative univer-flex univer-items-center univer-gap-2" onDrag={(e) => e.stopPropagation()}>
            <Input
                data-u-comp="search-input"
                autoFocus
                placeholder={localeService.t<LocaleKey>('find-replace.dialog.find-placeholder')}
                value={value}
                onChange={(value) => {
                    setValue(value);
                    onChange?.(value);
                }}
                slot={(
                    <Pager
                        loop
                        text={text}
                        value={matchesPosition}
                        total={matchesCount}
                        onChange={handleChangePosition}
                    />
                )}
                {...rest}
            />
        </div>
    );
}

# @univerjs/docs-find-replace

[![npm version](https://img.shields.io/npm/v/@univerjs/docs-find-replace?style=flat-square)](https://npmjs.com/package/@univerjs/docs-find-replace)
[![license](https://img.shields.io/npm/l/@univerjs/docs-find-replace?style=flat-square)](https://npmjs.com/package/@univerjs/docs-find-replace)
[![downloads](https://img.shields.io/npm/dm/@univerjs/docs-find-replace?style=flat-square)](https://npmjs.com/package/@univerjs/docs-find-replace)

`@univerjs/docs-find-replace` integrates the shared find-and-replace UI with Univer Docs.

## Package Overview

| Package | UMD global | CSS | Locales | Facade entry |
| --- | --- | :---: | :---: | :---: |
| `@univerjs/docs-find-replace` | `UniverDocsFindReplace` | No | No | No |

## Installation

```sh
pnpm add @univerjs/docs-find-replace @univerjs/find-replace
# or
npm install @univerjs/docs-find-replace @univerjs/find-replace
```

## Usage

```ts
import { LocaleType, mergeLocales, Univer } from '@univerjs/core';
import { UniverDocsFindReplacePlugin } from '@univerjs/docs-find-replace';
import { UniverFindReplacePlugin } from '@univerjs/find-replace';
import FindReplaceEnUS from '@univerjs/find-replace/locale/en-US';
import '@univerjs/find-replace/lib/index.css';

const univer = new Univer({
    locale: LocaleType.EN_US,
    locales: {
        [LocaleType.EN_US]: mergeLocales(FindReplaceEnUS),
    },
});

univer.registerPlugin(UniverFindReplacePlugin);
univer.registerPlugin(UniverDocsFindReplacePlugin);
```

## Integration Notes

Register the shared find-and-replace plugin before the Docs adapter so it can provide the common UI, locale strings, and services. Configure the rest of the Docs plugin stack before adding these two plugins.

Phase one searches and replaces literal text in the current document body, including tables. It excludes headers, footers, comments, drawings, regular expressions, formatting search, special characters, result sidebars, presets, and Facade APIs.

